      <Card style={{ marginBottom: 24 }}>
        <Space direction="vertical" style={{ width: '100%' }}>
          <Text strong>输入 URL：</Text>
          <TextArea
            value={inputUrl}
            onChange={(e) => setInputUrl(e.target.value)}
            rows={4}
            placeholder="请输入要处理的 URL，支持自动解析查询参数和 Hash 参数"
