  };

  const formatCSS = (css: string): string => {
    let formatted = css
      .replace(/\s+/g, ' ')
      .replace(/\s*\{\s*/g, ' {\n  ')
      .replace(/;\s*/g, ';\n  ')
      .replace(/\s*\}\s*/g, '\n}\n')
      .replace(/,\s*/g, ', ')
      .replace(/:\s*/g, ': ')
      .replace(/\n\s*\n/g, '\n')
